begin;select plan(31);
select has_table('public','crm_guest_profiles','profiles exist');select has_table('public','crm_consent_events','consents exist');select has_table('public','crm_lifecycle_events','lifecycle exists');select has_table('public','crm_retention_decisions','retention exists');
select has_function('public','crm_marketing_eligible',array['uuid'],'eligibility RPC exists');select ok(not has_function_privilege('service_role','public.record_crm_consent(uuid,text,text,text,timestamptz,text,text)','execute'),'service cannot record consent');select ok(not has_table_privilege('authenticated','public.crm_consent_events','insert'),'consent cannot be forged');select ok(not has_table_privilege('anon','public.crm_guest_profiles','select'),'anonymous denied');
insert into public.properties(id,name,is_active) values('f1000000-0000-4000-8000-000000000001','Synthetic CRM',true);
insert into public.guests(id,property_id,name) values('f3000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','Synthetic One'),('f3000000-0000-4000-8000-000000000002','f1000000-0000-4000-8000-000000000001','Synthetic Two');
insert into auth.users(id) values('f2000000-0000-4000-8000-000000000001'),('f2000000-0000-4000-8000-000000000002');insert into public.staff_access_profiles(user_id,role) values('f2000000-0000-4000-8000-000000000001','admin'),('f2000000-0000-4000-8000-000000000002','cleaner');insert into public.staff_property_access(user_id,property_id) values('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001'),('f2000000-0000-4000-8000-000000000002','f1000000-0000-4000-8000-000000000001');
set local role authenticated;set local request.jwt.claims='{"sub":"f2000000-0000-4000-8000-000000000001","aal":"aal1"}';select throws_ok($$select public.create_crm_profile('f3000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64),'wave6-profile-key-001')$$,'42501',null,'AAL1 denied');
set local request.jwt.claims='{"sub":"f2000000-0000-4000-8000-000000000001","aal":"aal2"}';select set_config('cascade.w6_profile',public.create_crm_profile('f3000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64),'wave6-profile-key-001')::text,true);
select is(public.create_crm_profile('f3000000-0000-4000-8000-000000000001',repeat('a',64),repeat('b',64),'wave6-profile-key-001'),current_setting('cascade.w6_profile')::uuid,'profile retry stable');select is(public.resolve_crm_identity('f1000000-0000-4000-8000-000000000001','email',repeat('a',64)),'f3000000-0000-4000-8000-000000000001'::uuid,'email resolves exactly');select is(public.resolve_crm_identity('f1000000-0000-4000-8000-000000000001','phone',repeat('b',64)),'f3000000-0000-4000-8000-000000000001'::uuid,'phone resolves exactly');select throws_ok($$select public.create_crm_profile('f3000000-0000-4000-8000-000000000002',repeat('a',64),repeat('c',64),'wave6-profile-key-002')$$,'23505','identity hash conflict','conflicting identity denied');
select is(public.crm_marketing_eligible(current_setting('cascade.w6_profile')::uuid),false,'no consent means ineligible');select lives_ok($$select public.record_crm_consent(current_setting('cascade.w6_profile')::uuid,'operational','granted',repeat('d',64),now(),'Operational contact','wave6-operational-consent')$$,'operational consent recorded');select is(public.crm_marketing_eligible(current_setting('cascade.w6_profile')::uuid),false,'operational consent is not marketing');
select set_config('cascade.w6_marketing',public.record_crm_consent(current_setting('cascade.w6_profile')::uuid,'marketing','granted',repeat('e',64),now(),'Marketing permission','wave6-marketing-consent1')::text,true);select is(public.crm_marketing_eligible(current_setting('cascade.w6_profile')::uuid),true,'marketing consent enables eligibility');select throws_ok($$select public.record_crm_consent(current_setting('cascade.w6_profile')::uuid,'marketing','withdrawn',repeat('e',64),now(),'Changed retry','wave6-marketing-consent1')$$,'22023','consent idempotency conflict','changed consent retry denied');
select throws_ok($$select public.record_crm_lifecycle(current_setting('cascade.w6_profile')::uuid,'recovery_opened','service_issue',repeat('f',64),null,false,now(),'Issue opened','wave6-recovery-open-bad')$$,'22023','invalid lifecycle record','recovery must suppress marketing');select lives_ok($$select public.record_crm_lifecycle(current_setting('cascade.w6_profile')::uuid,'recovery_opened','service_issue',repeat('f',64),null,true,now(),'Issue opened','wave6-recovery-open-001')$$,'recovery opened');select is(public.crm_marketing_eligible(current_setting('cascade.w6_profile')::uuid),false,'open recovery suppresses marketing');select lives_ok($$select public.record_crm_lifecycle(current_setting('cascade.w6_profile')::uuid,'recovery_resolved','service_issue',repeat('f',64),null,false,now()+interval '1 second','Issue resolved','wave6-recovery-resolve1')$$,'recovery resolved');select is(public.crm_marketing_eligible(current_setting('cascade.w6_profile')::uuid),true,'resolved recovery restores eligibility');
select lives_ok($$select public.record_crm_consent(current_setting('cascade.w6_profile')::uuid,'marketing','withdrawn',repeat('1',64),now()+interval '2 seconds','Permission withdrawn','wave6-marketing-withdraw1')$$,'withdrawal recorded');select is(public.crm_marketing_eligible(current_setting('cascade.w6_profile')::uuid),false,'withdrawal stops eligibility');select lives_ok($$select public.record_crm_consent(current_setting('cascade.w6_profile')::uuid,'marketing','granted',repeat('2',64),now()+interval '3 seconds','Permission restored','wave6-marketing-grant002')$$,'new grant recorded');
select set_config('cascade.w6_retention',public.record_crm_retention(current_setting('cascade.w6_profile')::uuid,'restrict',null,'Retention restriction','wave6-retention-restrict')::text,true);select is(public.crm_marketing_eligible(current_setting('cascade.w6_profile')::uuid),false,'retention restriction blocks marketing');select throws_ok($$select public.record_crm_retention(current_setting('cascade.w6_profile')::uuid,'delete_due',null,'Changed retry','wave6-retention-restrict')$$,'22023','retention idempotency conflict','changed retention retry denied');
set local request.jwt.claims='{"sub":"f2000000-0000-4000-8000-000000000002","aal":"aal2"}';select throws_ok($$select public.crm_marketing_eligible(current_setting('cascade.w6_profile')::uuid)$$,'42501',null,'OPS cannot inspect eligibility');select is((select count(*) from public.crm_consent_events),0::bigint,'OPS cannot browse consent');reset role;select is((select count(*) from public.crm_guest_profiles where email_hash=repeat('a',64)),1::bigint,'one deterministic profile retained');select * from finish();rollback;
